def transform(g):
    from collections import Counter
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    def bands(idxs):
        res=[];cur=[]
        for x in idxs:
            if cur and x==cur[-1]+1: cur.append(x)
            else:
                if cur: res.append(cur)
                cur=[x]
        if cur: res.append(cur)
        return res
    sep_rows={r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=bg}
    sep_cols={c for c in range(W) if len({g[r][c] for r in range(H)})==1 and g[0][c]!=bg}
    rb=bands([r for r in range(H) if r not in sep_rows])
    cb=bands([c for c in range(W) if c not in sep_cols])
    def nz(i,j):
        return sum(1 for r in rb[i] for c in cb[j] if g[r][c]!=bg)
    src=max(((i,j) for i in range(len(rb)) for j in range(len(cb))),key=lambda ij: nz(*ij))
    out=[row[:] for row in g]
    srb,scb=rb[src[0]],cb[src[1]]
    for i in range(len(rb)):
        for j in range(len(cb)):
            for a,r in enumerate(rb[i]):
                for b,c in enumerate(cb[j]):
                    out[r][c]=g[srb[a%len(srb)]][scb[b%len(scb)]]
    return out

